# ジャンケンの手と勝敗を数値で定義
ROCK = 0
SCISSORS = 1
PAPER = 2
DRAW = 0
LOSE = 1
WIN = 2

def janken_result(self, opponent):
    if self == opponent:
        return DRAW
    elif self == ROCK:
        if opponent == SCISSORS:
            return WIN
        else: # opponent == PAPER
            return LOSE
    elif self == SCISSORS:
        if opponent == PAPER:
            return WIN
        else: # opponent == ROCK
            return LOSE
    elif self == PAPER:
        if opponent == ROCK:
            return WIN
        else: # opponent == SCISSORS
            return LOSE

def display_result(N):
    if N == DRAW:
        print("あいこ")
    elif N == LOSE:
        print("負け")
    elif N == WIN:
        print("勝ち")

# 自分と相手の手を指定
self = int(input())
opponent = int(input())

result = janken_result(self, opponent)
display_result(result)

