import requests

# 初期設定
PX, PY = 1, 1  # プレイヤーの初始座標
W = 10  # タイル的宽度
SZ = 55  # 迷路的尺寸
maze_url = "https://n3s.nadesi.com/image.php?f=20.csv"
treasure_count = 0  # 宝的数量

# 获取迷路数据
response = requests.get(maze_url)
maze_data = response.text.strip().split('\n')
maze = [[int(tile) for tile in row.split(',')] for row in maze_data]

def draw_maze():
    # 绘制迷路
    for y in range(SZ):
        for x in range(SZ):
            V = maze[y][x]
            draw_tile(x, y, V)

def draw_tile(x, y, V):
    # 绘制单个瓷砖
    if V == 0:
        color = "#f0f0f0"  # 白色
    elif V == 1:
        color = "#8b4513"  # 棕色
    elif V == 2:
        color = "#ffff00"  # 黄色
    elif V == 3:
        color = "#ffff00"  # 黄色
    elif V == 4:
        color = "#ffff00"  # 黄色
    else:
        return

    print(f"[X{x*W},Y{y*W+7}]に「♪」の文字描画。")

def handle_key_event():
    global PX, PY
    pressed_key = input().strip()  # 获取按键输入
    if pressed_key == "ArrowUp":
        Y = PY - 1
    elif pressed_key == "ArrowDown":
        Y = PY + 1
    elif pressed_key == "ArrowLeft":
        X = PX - 1
    elif pressed_key == "ArrowRight":
        X = PX + 1
    else:
        return

    if (X != PX) or (Y != PY):
        # 检查移动是否有效
        if (X < 0) or (Y < 0) or (X >= SZ) or (Y >= SZ):
            print("戻る。")
            return
        M = maze[Y][X]
        if M == 1:
            print("戻る。")
            return
        elif M == 2:
            print("罠に捕まった！スタートに地点に戻ってしまった")
            PX, PY = 1, 1
            maze[Y][X] = 0
        elif M == 3:
            print("宝を見つけた！")
            treasure_count += 1
            maze[Y][X] = 0
        elif M == 4:
            if treasure_count == 0:
                print("出口を見つけたが、せっかくなら宝を持って帰りたい")
            else:
                print(f"宝を{treasure_count}個持ってゴール！ゲームクリア")
        PX, PY = X, Y  # 更新玩家位置
        draw_maze()

# 绘制初始迷路
draw_maze()

# 处理键盘事件
while True:
    handle_key_event()

