import random
import time

# データ＝[] # ブロックの値
data = []
DW = 90 # ブロック幅
shuffle_count = 0 # シャッフルの時利用する
image_url = "https://n3s.nadesi.com/image.php?f=16.png"

# 初期化処理。
def initialize():
    data.clear()
    for y in range(4):
        row = []
        for x in range(4):
            if x == 3 and y == 3:
                row.append(0) # 空きブロック
            else:
                row.append(1 + (y * 4 + x))
        data.append(row)

# マウスイベントの処理 --- (*1)
def on_mouse_down():
    y = int(mouse_y / DW)
    x = int(mouse_x / DW)
    if (0 <= y < 4 and 0 <= x < 4):
        move_block([y, x])
        draw_stage()
        time.sleep(0.1)
        if check_clear():
            initialize()

# ブロック初期化とは
def block_initialize():
    data.clear()
    for y in range(4):
        row = []
        for x in range(4):
            if x == 3 and y == 3:
                row.append(0) # 空きブロック
            else:
                row.append(1 + (y * 4 + x))
        data.append(row)
    shuffle_numbers()

# (YXの)ブロック移動とは # --- (*3)
def move_block(yx):
    y = yx[0]
    x = yx[1]
    ry, rx = -1, -1
    directions = [[-1, 0], [1, 0], [0, -1], [0, 1]]
    for direction in directions:
        fy = direction[0] + y
        fx = direction[1] + x
        if (fy < 0 or fy > 3) or (fx < 0 or fx > 3):
            continue
        v = data[fy][fx]
        if v == 0:
            ry, rx = fy, fx
            break
    if rx == -1:
        return
    tmp = data[y][x]
    data[y][x] = data[ry][rx]
    data[ry][rx] = tmp

# 番号シャッフルとは # --- (*4)
def shuffle_numbers():
    global shuffle_count
    shuffle_count = 0
    while True:
        if shuffle_count > 30:
            break
        y = random.randint(0, 3)
        x = random.randint(0, 3)
        move_block([y, x])
        if check_clear():
            break
        draw_stage()
        time.sleep(0.1)
        shuffle_count += 1

# クリア確認とは # --- (*6)
def check_clear():
    for y in range(4):
        for x in range(4):
            v = data[y][x]
            if v == 0:
                continue
            if v != (y * 4 + x + 1):
                return False
    print("ゲームクリア")
    return True

# ステージ描画とは
def draw_stage():
    for y in range(4):
        for x in range(4):
            draw_tile(x, y)

# (XとYに)タイル描画とは
def draw_tile(x, y):
    v = data[y][x] - 1
    if v == -1:
        v = 15
    sx = DW * (v % 4)
    sy = DW * int(v // 4)
    dx = DW * x
    dy = DW * y
    # 画像URLの[sx,sy,dw,dw]を[dx,dy,dw,dw]へ画像部分描画。
    pass  # 実際には画像描画が必要ですが、ここでは省略します

# メインループ
initialize()
while True:
    on_mouse_down()


